DO $assert$DECLARE r record;BEGIN
 IF(SELECT count(*)FROM saas.store_tool_offers)<>6 OR EXISTS(SELECT 1 FROM(VALUES('contact_widget',99000::bigint),('whatsapp_ordering',249000),('cart_capture',349000),('restock',449000),('order_bump',599000),('all_tools',1399000))q(id,net)LEFT JOIN saas.store_tool_offers o ON o.id=q.id WHERE o.id IS NULL OR o.net_cents<>q.net OR o.vat_bps<>2000 OR o.version<>1 OR o.quote_fingerprint<>encode(sha256(convert_to('store-tools:1:'||o.id||':'||o.net_cents::text||':2000','UTF8')),'hex'))THEN RAISE EXCEPTION 'STORE_TOOL263_OFFER_INVALID';END IF;
 IF(SELECT count(*)FROM saas.store_tools263_functions)<>6 THEN RAISE EXCEPTION 'STORE_TOOL263_MANIFEST_INVALID';END IF;
 FOR r IN SELECT *FROM saas.store_tools263_functions LOOP IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=r.function_oid AND p.oid=to_regprocedure(r.signature)AND p.proowner=r.function_owner AND p.proacl IS NOT DISTINCT FROM r.function_acl AND p.proconfig IS NOT DISTINCT FROM r.function_config AND p.prosecdef=r.function_security AND p.provolatile=r.function_volatility AND p.proisstrict=r.function_strict AND p.proparallel=r.function_parallel AND p.prolang=r.function_language AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')=r.published_sha256)OR encode(sha256(convert_to(r.definition,'UTF8')),'hex')<>r.original_sha256 THEN RAISE EXCEPTION 'STORE_TOOL263_SOURCE_DRIFT:%',r.signature;END IF;END LOOP;
 IF EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=ANY(ARRAY['saas.store_tool_offers'::regclass,'saas.store_tool_purchases'::regclass,'saas.store_tool_receipts'::regclass,'saas.store_tool_licenses'::regclass,'saas.store_tools263_functions'::regclass])AND(NOT c.relrowsecurity OR NOT c.relforcerowsecurity OR c.relowner<>'celebix_saas_owner'::regrole))THEN RAISE EXCEPTION 'STORE_TOOL263_RLS_INVALID';END IF;
 IF EXISTS(SELECT 1 FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))g WHERE p.pronamespace='saas'::regnamespace AND(p.proname LIKE 'store_tool_%'OR p.proname IN('platform_tool_purchases_read','platform_tool_purchase_settle'))AND g.grantee=0 AND g.privilege_type='EXECUTE')THEN RAISE EXCEPTION 'STORE_TOOL263_PUBLIC_AUTHORITY_INVALID';END IF;
 IF NOT has_function_privilege('celebix_saas_app','saas.store_tool_workspace_read(uuid,uuid,uuid,uuid,text,bigint,timestamptz)','EXECUTE')OR NOT has_function_privilege('celebix_saas_app','saas.store_tool_purchase_request(uuid,uuid,uuid,uuid,text,bigint,timestamptz,uuid,text,text)','EXECUTE')OR NOT has_function_privilege('celebix_saas_platform_operator','saas.platform_tool_purchase_settle(uuid,uuid,bigint,text,jsonb)','EXECUTE')OR has_function_privilege('celebix_saas_app','saas.platform_tool_purchase_settle(uuid,uuid,bigint,text,jsonb)','EXECUTE')OR has_function_privilege('celebix_saas_host_resolver','saas.store_tool_workspace_read(uuid,uuid,uuid,uuid,text,bigint,timestamptz)','EXECUTE')THEN RAISE EXCEPTION 'STORE_TOOL263_RPC_AUTHORITY_INVALID';END IF;
 IF EXISTS(SELECT 1 FROM saas.store_tool_purchases p LEFT JOIN saas.store_tool_receipts receipt_row ON receipt_row.store_id=p.store_id AND receipt_row.purchase_id=p.id WHERE(p.status='settled')IS DISTINCT FROM(receipt_row.purchase_id IS NOT NULL)OR(receipt_row.purchase_id IS NOT NULL AND receipt_row.amount_cents<>p.total_cents))OR EXISTS(SELECT 1 FROM saas.store_tool_licenses l JOIN saas.store_tool_purchases p ON p.store_id=l.store_id AND p.id=l.purchase_id WHERE l.source='purchase'AND(p.status<>'settled'OR NOT l.tool_key=ANY(p.tool_keys)))THEN RAISE EXCEPTION 'STORE_TOOL263_PAYMENT_LICENSE_MISMATCH';END IF;
END $assert$;
